(()=>{
const $=id=>document.getElementById(id),money=n=>new Intl.NumberFormat('pl-PL',{style:'currency',currency:'PLN'}).format(n),number=(n,d=3)=>new Intl.NumberFormat('pl-PL',{maximumFractionDigits:d}).format(n);
const DEFAULT_BASE=3,OUNCE=31.1034768;
function baseRate(){return DEFAULT_BASE;}
function priceRate(purity){const live=Number(window.silverLivePrices?.[purity]);if(!Number.isFinite(live)||live<=0)throw Error("Poczekaj na pobranie aktualnego cennika.");return live;}
const presets={coins:[['ounce','Moneta 1 oz · próba 999','31.10',999],['half','Moneta 1/2 oz · próba 999','15.55',999],['custom','Własna moneta — podaj parametry',null,null]],bars:[['100','Sztabka 100 g · próba 999',100,999],['ounce','Sztabka 1 oz · próba 999','31.10',999],['250','Sztabka 250 g · próba 999',250,999],['500','Sztabka 500 g · próba 999',500,999],['1000','Sztabka 1 kg · próba 999',1000,999],['custom','Własna sztabka — podaj parametry',null,null]],scrap:[['jewelry','Biżuteria / złom srebrny',null,null],['cutlery','Sztućce / srebro użytkowe',null,null]]};
const labels={coins:'Monety',bars:'Sztabki',scrap:'Biżuteria i złom'};
let kind='scrap',items=[],current=null,nextId=1;
function configureCategory(value){if(!presets[value])throw Error('Nieznany rodzaj srebra');kind=value;document.querySelectorAll('[data-kind]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.kind===kind));$('preset').replaceChildren(...presets[kind].map(p=>new Option(p[1],p[0])));$('quantity-label').hidden=kind==='scrap';$('deduction-label').hidden=kind!=='scrap';$('weight-label').textContent='Waga (g)';$('calc-help').textContent=kind==='scrap'?'':'Wycena dotyczy zawartości metalu. Wartość kolekcjonerska nie jest uwzględniona.';$('quantity').value='1';$('deduction').value='0';if(kind==='scrap'){$('weight').value='';$('purity').value=925;}applyPreset();}
function applyPreset(){const p=presets[kind].find(p=>p[0]===$('preset').value),locked=kind!=='scrap'&&p?.[2]!=null;if(p?.[2]!=null){$('weight').value=p[2];$('purity').value=p[3];}$('weight').readOnly=locked;$('purity').disabled=locked;updateCalc();}
function calculate(k,w,p,q,d,productPrice=null){if(!presets[k])throw Error('Wybierz rodzaj srebra.');if(!Number.isFinite(w)||w<=0||w>1000000)throw Error('Podaj wagę większą od 0 i nie większą niż 1 000 000 g.');const available=Object.keys(window.silverLivePrices||{800:1,830:1,835:1,875:1,900:1,925:1,999:1}).map(Number);if(!available.includes(p))throw Error('Wybierz prawidłową próbę.');if(!Number.isInteger(q)||q<1||q>10000)throw Error('Liczba sztuk musi być całkowita, od 1 do 10 000.');if(!Number.isFinite(d)||d<0||d>=w)throw Error('Masa pozostałych części musi być mniejsza niż waga przedmiotu.');const net=(w-d)*q,fine=net*p/1000,hasProductPrice=Number.isFinite(productPrice)&&productPrice>0,rate=hasProductPrice?productPrice/w:priceRate(p),value=hasProductPrice?productPrice*q:net*rate;return {kind:k,weight:w,purity:p,quantity:q,deduction:d,net,fine,value,rate};}
function updateCalc(){if(!$('weight').value.trim()){current=null;document.querySelector('.calc-result')?.classList.add('awaiting-parameters');$('calc-error').hidden=true;$('result').textContent='Wpisz wagę';['net-weight','fine-weight','gram-rate'].forEach(id=>$(id).textContent='—');$('add-item').disabled=true;return;}try{if($('weight').value===''||(kind!=='scrap'&&$('quantity').value==='')||(kind==='scrap'&&$('deduction').value===''))throw Error('Uzupełnij wszystkie pola liczbowe.');const selected=presets[kind].find(p=>p[0]===$('preset').value),productPrice=kind==='scrap'?null:selected?.[4];current=calculate(kind,+$('weight').value,+$('purity').value,kind==='scrap'?1:+$('quantity').value,kind==='scrap'?+$('deduction').value:0,productPrice);document.querySelector('.calc-result')?.classList.remove('awaiting-parameters');$('calc-error').hidden=true;$('result').textContent=money(current.value);$('net-weight').textContent=number(current.net)+' g';$('fine-weight').textContent=number(current.fine)+' g';$('gram-rate').textContent=number(current.rate)+' zł';$('add-item').disabled=false;}catch(e){current=null;$('calc-error').hidden=false;$('calc-error').textContent=e.message;$('result').textContent='—';['net-weight','fine-weight','gram-rate'].forEach(id=>$(id).textContent='—');$('add-item').disabled=true;}}
function renderBasket(){$('basket-list').replaceChildren();for(const item of items){const li=document.createElement('li'),desc=document.createElement('div'),title=document.createElement('b'),detail=document.createElement('span'),value=document.createElement('strong'),remove=document.createElement('button');title.textContent=labels[item.kind]+' · próba '+item.purity;detail.textContent=`${item.quantity>1?item.quantity+' szt. × ':''}${number(item.weight)} g${item.deduction?' − '+number(item.deduction)+' g innych części':''}`;desc.append(title,detail);value.textContent=money(item.value);remove.textContent='Usuń';remove.className='text-button';remove.setAttribute('aria-label','Usuń '+labels[item.kind]+' z wyceny');remove.onclick=()=>{items=items.filter(i=>i.id!==item.id);renderBasket();};li.append(desc,value,remove);$('basket-list').append(li);}$('empty-basket').hidden=!!items.length;$('item-count').textContent=items.length;$('basket-total').textContent=money(items.reduce((s,i)=>s+i.value,0));['copy-quote','ask-quote','reset-valuation-basket'].forEach(id=>$(id).disabled=!items.length);$('copy-status').textContent='';}
function quoteText(){return 'Orientacyjna wycena srebra\n'+items.map((i,index)=>`${index+1}. ${labels[i.kind]}, próba ${i.purity}, masa netto ${number(i.net)} g: ${money(i.value)}`).join('\n')+'\nRazem: '+money(items.reduce((s,i)=>s+i.value,0))+'\nWycena według cennika skupu. Ostateczna wartość wymaga potwierdzenia masy i próby w punkcie.';}
async function copyText(text,status){try{await navigator.clipboard.writeText(text);$(status).textContent='Skopiowano.';}catch{$(status).textContent='Kopiowanie niedostępne. Zaznacz i skopiuj tekst ręcznie.';if(status==='copy-status'){let box=$('quote-fallback');if(!box){box=document.createElement('textarea');box.id='quote-fallback';box.readOnly=true;box.setAttribute('aria-label','Podsumowanie do ręcznego skopiowania');$('basket-list').after(box);}box.value=text;box.focus();box.select();}}}
function resetValuation(){items=[];configureCategory('scrap');$('weight').value='';current=null;document.querySelector('.calc-result')?.classList.add('awaiting-parameters');$('calc-error').hidden=true;$('result').textContent='Wybierz parametry';$('net-weight').textContent='0 g';$('fine-weight').textContent='0 g';$('gram-rate').textContent='0 zł';$('add-item').disabled=true;renderBasket();}
(function attachCalculator(){
  const form=document.getElementById('calc-form'),quick=document.querySelector('.quick-quote');
  function read(key){try{return JSON.parse(sessionStorage.getItem(key)||'null');}catch{return null;}}
  function store(key,value){try{sessionStorage.setItem(key,JSON.stringify(value));}catch{}}
  let intent=read('silver-intent');try{sessionStorage.removeItem('silver-intent');}catch{}
  let restored=false;const saved=read('silver-valuation');
  presets.scrap=[['jewelry','Biżuteria srebrna',null,null],['cutlery','Sztućce srebrne',null,null],['utility','Srebro użytkowe',null,null],['granulate','Granulat srebrny',null,null]];
  function save(){if(!form)return;store('silver-valuation',{items,kind,fields:Object.fromEntries(['weight','purity','quantity','deduction','preset'].map(id=>[id,$(id).value]))});}
  if(form){if(Array.isArray(saved?.items)){items=saved.items.filter(i=>Number.isFinite(i.value)&&Number.isFinite(i.net)).slice(0,1000);nextId=Math.max(0,...items.map(i=>Number(i.id)||0))+1;}document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{configureCategory(b.dataset.kind);save();});$('preset').onchange=()=>{if(kind==='scrap'&&$('preset').value==='granulate')$('purity').value='999';applyPreset();save();};['weight','purity','quantity','deduction'].forEach(id=>$(id).addEventListener('input',()=>{if(['weight','purity'].includes(id)&&kind!=='scrap')$('preset').value='custom';updateCalc();save();}));form.onsubmit=e=>{e.preventDefault();updateCalc();if(current){items.push({...current,id:nextId++});renderBasket();save();document.querySelector('.basket').scrollIntoView({behavior:'smooth',block:'start'});}};['reset-valuation','reset-valuation-mobile','reset-valuation-basket'].forEach(id=>$(id)?.addEventListener('click',()=>{resetValuation();save();}));$('copy-quote').onclick=()=>copyText(quoteText(),'copy-status');$('ask-quote').onclick=()=>{try{sessionStorage.setItem('silver-contact-draft','Dzień dobry, proszę o wycenę poniższych przedmiotów.\n\n'+quoteText());}catch{}save();location.href='/kontakt.html';};window.addEventListener('pagehide',save);renderBasket();$('add-item').disabled=true;}
  function quickValue(){if(!quick)return;const weight=$('quick-weight'),purity=$('quick-purity'),result=$('quick-result'),error=$('quick-error');if(!weight.value.trim()){result.textContent='Wpisz wagę';error.hidden=true;return null;}try{const v=calculate('scrap',Number(weight.value),Number(purity.value),1,0);result.textContent=money(v.value);error.hidden=true;return v;}catch(e){result.textContent='—';error.textContent=e.message;error.hidden=false;return null;}}
  if(quick){$('quick-weight').addEventListener('input',quickValue);$('quick-purity').addEventListener('change',quickValue);quick.onsubmit=e=>{e.preventDefault();if(!quickValue())return;store('silver-intent',{kind:'scrap',weight:$('quick-weight').value,purity:$('quick-purity').value});location.href='/wycena.html';};quickValue();}
  document.addEventListener('silver-prices-ready',event=>{const payload=event.detail;const toPreset=(p)=>[p.id,p.name+' · próba '+String(p.purity).replace('.',','),p.grossWeight,Number(p.purity)>=999?999:Number(p.purity),Number(p.price)];presets.coins=(payload.products?.silverCoins||[]).map(toPreset).concat([['custom','Własna moneta — podaj parametry',null,null]]);presets.bars=(payload.products?.silverBars||[]).map(toPreset).concat([['custom','Własna sztabka — podaj parametry',null,null]]);for(const id of ['purity','quick-purity']){const field=$(id);if(!field)continue;const chosen=field.value;field.replaceChildren(...Object.keys(window.silverLivePrices).map(p=>new Option((id==='quick-purity'?'Próba ':'')+(p==='999'?'999,9':p),p)));field.value=chosen in window.silverLivePrices?chosen:'925';}if(form){const state=!restored?saved:null;const fields=intent?{}:state?.fields||Object.fromEntries(['weight','purity','quantity','deduction','preset'].map(id=>[id,$(id).value]));configureCategory(intent?.kind||state?.kind||kind);for(const[id,val]of Object.entries(fields))if($(id)&&val!==undefined)$(id).value=val;if(intent?.purity)$('purity').value=intent.purity;if(intent?.weight)$('weight').value=intent.weight;applyPreset();restored=true;intent=null;save();}quickValue();});
})();
})();

